INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('ranunculus', 340, '{"key":"ranunculus","name":"Ranunkel från knöl","genera":["Ranunculus"],"scientificPrefixes":[],"startingUnits":["TUBER"],"plantTypes":["TUBER"],"reviewRequired":false,"harvestMonths":[5,6,7],"plantingMonths":[],"description":"Vårstart i sval, skyddad odling. Blötlägg och förgro knölar enligt leverantörens råd; cirka tre veckors sval förgroning. Skydda mot hård frost och hög värme. Butterfly-sorter har ett annat skördestadium.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":85,"startingUnit":"TUBER","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":147,"quantityBasis":"START"},{"key":"start","name":"Plantera utgångsmaterial","activityType":"PLANT","daysBeforeHarvest":126,"quantityBasis":"START"},{"key":"harden","name":"Börja avhärda – kontrollera lokal frostrisk","activityType":"TODO","daysBeforeHarvest":112,"quantityBasis":"PLANT"},{"key":"plant-out","name":"Plantera ut när väder och jordtemperatur tillåter","activityType":"PLANT","daysBeforeHarvest":105,"quantityBasis":"PLANT"},{"key":"check","name":"Kontrollera etablering, vattenbehov och växtstöd","activityType":"TODO","daysBeforeHarvest":52,"quantityBasis":"PLANT"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":340,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"Johnny’s: growing ranunculus","url":"https://prod-na02.johnnyseeds.com/growers-library/flowers/ranunculus/ranunculus-key-growing-information.html"}]}'::jsonb);
