INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('spring-bulb', 360, '{"key":"spring-bulb","name":"Höstplanterade vårblommande lökar","genera":["Tulipa","Narcissus","Crocus","Muscari","Hyacinthus","Galanthus","Leucojum","Scilla","Chionodoxa","Allium","Fritillaria"],"scientificPrefixes":[],"startingUnits":["BULB"],"plantTypes":["BULB"],"reviewRequired":false,"harvestMonths":[3,4,5,6,7],"plantingMonths":[9,10,11],"description":"Plantera blomningsmogna lökar föregående höst. Naturlig vinterkyla krävs. Välj mål inom sortens normala blomning, inte valfri drivning. Kontrollera sortens blomningsmånad och höstens planteringsdatum.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":90,"startingUnit":"BULB","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":231,"quantityBasis":"START"},{"key":"start","name":"Plantera utgångsmaterial","activityType":"PLANT","daysBeforeHarvest":210,"quantityBasis":"START"},{"key":"check","name":"Kontrollera etablering, vattenbehov och växtstöd","activityType":"TODO","daysBeforeHarvest":105,"quantityBasis":"PLANT"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":360,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"RHS: planting bulbs","url":"https://www.rhs.org.uk/plants/types/bulbs/planting"}]}'::jsonb);
