INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('peony', 380, '{"key":"peony","name":"Pion – etablering från rot/planta","genera":["Paeonia"],"scientificPrefixes":[],"startingUnits":["PLANT"],"plantTypes":["PERENNIAL"],"reviewRequired":true,"harvestMonths":[5,6,7],"plantingMonths":[],"description":"Nyplanterade pioner behöver etableras under flera säsonger. Ange verkligt antal år till försiktig första skörd utifrån plantans ålder; skörda inte nyplanterade rötter som etablerade plantor.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":85,"startingUnit":"PLANT","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":null,"quantityBasis":"START"},{"key":"start","name":"Plantera utgångsmaterial","activityType":"PLANT","daysBeforeHarvest":null,"quantityBasis":"START"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":380,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"RHS: growing peonies","url":"https://www.rhs.org.uk/plants/peony/herbaceous/growing-guide"}]}'::jsonb);
INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('biennial', 390, '{"key":"biennial","name":"Tvåårig blomma – sådd och övervintring","genera":[],"scientificPrefixes":[],"startingUnits":["SEED"],"plantTypes":["BIENNIAL"],"reviewRequired":true,"harvestMonths":[5,6,7,8],"plantingMonths":[],"description":"Grundstruktur: så föregående sommar, etablera bladrosett, övervintra och skörda nästa säsong. Bekräfta artens kylbehov och kalender. Förstaårsblommande sorter behöver en annan tidsplan.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":70,"startingUnit":"SEED","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":441,"quantityBasis":"START"},{"key":"start","name":"Så","activityType":"SOW","daysBeforeHarvest":420,"quantityBasis":"START"},{"key":"pot-up","name":"Skola om vid utvecklade karaktärsblad","activityType":"POT_UP","daysBeforeHarvest":399,"quantityBasis":"PLANT"},{"key":"harden","name":"Börja avhärda – kontrollera lokal frostrisk","activityType":"TODO","daysBeforeHarvest":371,"quantityBasis":"PLANT"},{"key":"plant-out","name":"Plantera ut när väder och jordtemperatur tillåter","activityType":"PLANT","daysBeforeHarvest":364,"quantityBasis":"PLANT"},{"key":"check","name":"Kontrollera etablering, vattenbehov och växtstöd","activityType":"TODO","daysBeforeHarvest":182,"quantityBasis":"PLANT"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":390,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"Johnny’s Flower Growing Guide","url":"https://www.johnnyseeds.com/on/demandware.static/-/Library-Sites-JSSSharedLibrary/default/dw377bb4f5/assets/information/flower-growing-guide.pdf"}]}'::jsonb);
INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('annual-review', 400, '{"key":"annual-review","name":"Ettårig blomma – sortanpassning krävs","genera":[],"scientificPrefixes":[],"startingUnits":["SEED"],"plantTypes":["ANNUAL"],"reviewRequired":true,"harvestMonths":[6,7,8,9],"plantingMonths":[],"description":"Generellt utkast för ettårig odling. Bekräfta direktsådd eller förodling, sortens tid till blomning och lämpligt skördestadium innan planen används.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":70,"startingUnit":"SEED","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":133,"quantityBasis":"START"},{"key":"start","name":"Så","activityType":"SOW","daysBeforeHarvest":112,"quantityBasis":"START"},{"key":"pot-up","name":"Skola om vid utvecklade karaktärsblad","activityType":"POT_UP","daysBeforeHarvest":91,"quantityBasis":"PLANT"},{"key":"harden","name":"Börja avhärda – kontrollera lokal frostrisk","activityType":"TODO","daysBeforeHarvest":77,"quantityBasis":"PLANT"},{"key":"plant-out","name":"Plantera ut när väder och jordtemperatur tillåter","activityType":"PLANT","daysBeforeHarvest":70,"quantityBasis":"PLANT"},{"key":"check","name":"Kontrollera etablering, vattenbehov och växtstöd","activityType":"TODO","daysBeforeHarvest":35,"quantityBasis":"PLANT"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":400,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"Johnny’s Flower Growing Guide","url":"https://www.johnnyseeds.com/on/demandware.static/-/Library-Sites-JSSSharedLibrary/default/dw377bb4f5/assets/information/flower-growing-guide.pdf"}]}'::jsonb);
INSERT INTO shared_production_schedule (key, priority, definition) VALUES ('perennial-seed', 410, '{"key":"perennial-seed","name":"Flerårig växt från frö – etablering","genera":[],"scientificPrefixes":[],"startingUnits":["SEED"],"plantTypes":["PERENNIAL"],"reviewRequired":true,"harvestMonths":[],"plantingMonths":[],"description":"Kontrollera artens stratifiering, groning, övervintring och ålder vid första blomning. Vedartade växter kan kräva många år. Fyll i tid till första hållbara skörd; en generell dagangivelse vore missvisande.","profile":{"sellableUnit":"STEM","outputPerPlant":1,"establishmentPercent":70,"startingUnit":"SEED","steps":[{"key":"purchase","name":"Beställ utgångsmaterial","activityType":"PURCHASE","daysBeforeHarvest":null,"quantityBasis":"START"},{"key":"start","name":"Så","activityType":"SOW","daysBeforeHarvest":null,"quantityBasis":"START"},{"key":"harvest","name":"Skörda i rätt mognadsstadium","activityType":"HARVEST","daysBeforeHarvest":0,"quantityBasis":"OUTPUT"}]},"priority":410,"revision":0,"autoMatch":true,"useSpeciesTiming":true,"version":"2026-10-05","climate":"Mellansverige: friland med förodling inomhus; lokal frost och sort avgör exakta datum.","sources":[{"title":"RHS: growing perennials from seed","url":"https://www.rhs.org.uk/membership/rhs-members-seed-scheme/germination-guide"}]}'::jsonb);
