-- Initial schedules are an immutable snapshot of the 2026-10-05 catalogue.
-- Later admin edits are database records and are never reseeded on startup.
CREATE TABLE shared_production_schedule (
    key VARCHAR(80) PRIMARY KEY,
    priority INTEGER NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1,
    definition JSONB NOT NULL
);
CREATE TABLE species_shared_schedule (
    species_id BIGINT PRIMARY KEY REFERENCES species(id) ON DELETE CASCADE,
    schedule_key VARCHAR(80) NOT NULL REFERENCES shared_production_schedule(key) ON DELETE RESTRICT
);
CREATE INDEX idx_species_shared_schedule_key ON species_shared_schedule(schedule_key);

